+// Estándar de empresa (brain: estandares/documentos-fiscales.md): SSS-AAAA-NNNNNN.
+// Un valor fuera de rango es un error: nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const entero = (valor, min, max, nombre) => {
+    if (!Number.isInteger(valor) || valor < min || valor > max)
+      throw new RangeError(`${nombre} inválido: debe ser un entero entre ${min} y ${max}`);
+    return String(valor);
+  };
+  const sss = entero(sucursal, 1, 999, "Sucursal").padStart(3, "0");
+  const aaaa = entero(gestion, 1000, 9999, "Gestión");
+  const nnnnnn = entero(correlativo, 1, 999999, "Correlativo").padStart(6, "0");
+  return `${sss}-${aaaa}-${nnnnnn}`;
+}
